 TABLE(["Показатель","До МСФО 16","После МСФО 16"],[["Аренда в расходах EBITDA","−40","0"],["EBITDA","160","200"],["Чистый долг (+ обязательство по аренде 160)","400","560"],["Чистый долг / EBITDA","2,5","2,8"]],(1,2)),
